Translate("esMX", "the-deadmines", {
	title = "Las Minas de la Muerte",
	aliases = { "Minas de la Muerte" },
	sections = {
		{
			title = "Resumen",
			text = [=[Las Minas de la Muerte se extienden bajo la aldea de {link:moonbrook}Arroyo de la Luna{/link}, en {link:westfall}Páramos de Poniente{/link}. En otro tiempo fueron las minas de oro más ricas de las tierras humanas. Hoy son el corazón secreto de la {link:defias-brotherhood}Hermandad Defias{/link}. En sus profundidades, los canteros de {link:edwin-vancleef}Edwin VanCleef{/link} y los goblins que han contratado construyen algo que nadie en {link:stormwind-city}Ventormenta{/link} ha visto todavía: un gran buque de guerra, oculto en una cueva marina en el fondo de las minas.]=],
		},
		{
			title = "Orígenes",
			text = [=[Durante generaciones, las minas bajo {link:moonbrook}Arroyo de la Luna{/link} enviaron oro al tesoro del {link:kingdom-of-stormwind}Reino de Ventormenta{/link}. Cuando la {link:horde}Horda{/link} arrasó {link:stormwind-city}Ventormenta{/link} en la {link:first-war}Primera Guerra{/link}, los mineros huyeron y los trabajos quedaron en silencio. Los túneles quedaron abandonados a la oscuridad, y la gente empezó a llamarlos las Minas de la Muerte. Permanecieron vacíos durante los años del exilio y de la reconstrucción. Cuando los canteros traicionados llegaron al oeste, encontraron una fortaleza ya excavada para ellos.]=],
		},
		{
			title = "El presente",
			text = [=[La {link:syndicate}Hermandad{/link} ha hecho de la vieja mina su santuario. Mineros {link:defias-brotherhood}Defias{/link} cavan en sus pozos, y magos y evocadores de la Hermandad guardan sus salas. Artesanos e ingenieros goblins a sueldo de la Hermandad cortan madera, funden metal y montan máquinas. Un {link:ogres}ogro{/link} guarda la primera puerta. Muy abajo, donde los túneles se abren al mar, el barco está casi listo, y su capitán y su tripulación esperan la orden de su amo. Qué pretende hacer {link:edwin-vancleef}VanCleef{/link} con él, solo la Hermandad lo sabe. Muchos temen que esté destinado a {link:stormwind-city}Ventormenta{/link}.]=],
		},
		{
			title = "Dentro de las minas",
			text = [=[• {b}El ala derrumbada.{/b} Antes de la entrada de la {link:syndicate}Hermandad{/link}, un pasaje lateral lleva a unos túneles donde un grupo de mineros y exploradores enanos quedó sepultado cuando se hundió el techo. No descansan. Sus muertos aún recorren la oscuridad con picos y dinamita.
• {b}La sala del mástil.{/b} Aquí los goblins del maestro maderero {link:sneed}Sneed{/link} cortan grandes vigas para el barco.
• {b}La fundición.{/b} Aquí el goblin {link:gilnid}Gilnid{/link} funde el metal de las minas.
• {b}{link:ironclad-cove}Cala del Acorazado{/link}.{/b} En el fondo de las minas hay una cueva abierta al mar, donde el barco de la Hermandad está fondeado. Su puerta está sellada, y solo la pólvora y el cañón la abrirán.
• {b}La salida oculta.{/b} Desde la cala, un pasaje sube hasta las colinas que hay detrás de {link:moonbrook}Arroyo de la Luna{/link}, cerca del mar.]=],
		},
		{
			title = "Los que moran abajo",
			text = [=[Los servidores de la {link:syndicate}Hermandad{/link} son muchos aquí. El capataz {link:rhahkzor}Rhahk'Zor{/link}, los goblins {link:sneed}Sneed{/link} y {link:gilnid}Gilnid{/link} y la tripulación del barco a las órdenes del capitán {link:captain-greenskin}Greenskin{/link} obedecen todos a {link:edwin-vancleef}Edwin VanCleef{/link}. En los túneles acechan también peligros más raros, entre ellos un minero de gran fuerza conocido como el minero Johnson.]=],
		},
	},
})

Translate("esMX", "ironclad-cove", {
	title = "Cala del Acorazado",
	sections = {
		{
			title = "Resumen",
			text = [=[La Cala del Acorazado es una enorme cueva marina en el fondo de las {link:the-deadmines}Minas de la Muerte{/link}, donde los túneles de las viejas minas de oro se abren a Mare Magnum. Aquí la {link:defias-brotherhood}Hermandad Defias{/link} guarda su mayor secreto. Un buque de guerra está fondeado en el agua oscura, construido con madera cortada en la sala del mástil y metal fundido en la fundición. Piratas de la {link:syndicate}Hermandad{/link} forman su tripulación. Desde su cubierta superior, {link:edwin-vancleef}Edwin VanCleef{/link} dirige a toda su Hermandad, y es aquí donde ha decidido resistir.]=],
		},
	},
})

Translate("esMX", "edwin-vancleef", {
	title = "Edwin VanCleef",
	subtitle = "Cabecilla de la Hermandad Defias",
	found = "La cubierta superior del barco en la Cala del Acorazado",
	hint = [=[Infórmese sobre él con la milicia de Páramos de Poniente, o búsquelo en el fondo de las Minas de la Muerte.]=],
	allegiance = "Hermandad Defias · antes el Gremio de Canteros",
	aliases = { "VanCleef", "Edwin" },
	sections = {
		{
			title = "Resumen",
			text = [=[Edwin VanCleef era el maestro del {link:stonemasons-guild}Gremio de Canteros{/link} de {link:stormwind-city}Ventormenta{/link}. Fue su gremio el que levantó de nuevo la capital de las cenizas de la {link:first-war}Primera Guerra{/link}. Cuando el trabajo estuvo hecho, la {link:house-of-nobles}Cámara de los Nobles{/link} se negó a pagar a los canteros lo que se les debía. VanCleef los llevó a la revuelta y dejó la ciudad jurando venganza. Hoy es el cabecilla de la {link:defias-brotherhood}Hermandad Defias{/link}, amo de {link:westfall}Páramos de Poniente{/link}, y desde una cala oculta bajo la tierra prepara su golpe contra el reino que lo traicionó.]=],
		},
		{
			title = "Importancia",
			text = [=[VanCleef es la herida que {link:stormwind-city}Ventormenta{/link} se causó a sí misma. Era un constructor, no un bandido, y quienes lo conocieron recuerdan a un hombre talentoso y trabajador. Su {link:syndicate}Hermandad{/link} nació de una injusticia real. Sin embargo, su venganza ha caído con más dureza sobre la gente sencilla de {link:westfall}Páramos de Poniente{/link} que sobre los nobles que lo engañaron, y ha llevado a la ruina al granero del propio reino.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Dirigió el {link:stonemasons-guild}Gremio de Canteros{/link} en la reconstrucción de {link:stormwind-city}Ventormenta{/link} después de las guerras.
• Cuando a algunos canteros veteranos se les ofrecieron cargos en el gobierno, rechazó el suyo por lealtad a todo el gremio.
• Encabezó el motín de los canteros y huyó de la ciudad al final. La reina {link:tiffin-wrynn}Tiffin Wrynn{/link} murió en el caos.
• Reunió a los canteros exiliados en {link:westfall}Páramos de Poniente{/link} y fundó la {link:defias-brotherhood}Hermandad Defias{/link}.
• Tomó las {link:the-deadmines}Minas de la Muerte{/link} como fortaleza y contrató goblins para construir un buque de guerra en sus profundidades.
• Su lugarteniente, {link:bazil-thredd}Bazil Thredd{/link}, fue capturado y encerrado en {link:the-stockade}Las Mazmorras{/link} de Ventormenta.]=],
		},
		{
			title = "Sin registro",
			text = [=[Ninguna crónica registra el nacimiento de VanCleef, su familia ni los años anteriores a que se convirtiera en maestro del gremio. Esta entrada recoge solo sus hechos y las palabras de quienes lo conocieron.]=],
		},
	},
	chapters = {
		{
			title = "Un nombre del pasado",
			hint = "Lleve la pregunta sobre los canteros al SI:7.",
			text = [=[Durante mucho tiempo la {link:syndicate}Hermandad{/link} no tuvo rostro. Entonces {link:master-mathias-shaw}Mathias Shaw{/link}, del {link:si-7}SI:7{/link}, le dio uno. El antiguo gremio de canteros, escribió, estaba dirigido por un hombre llamado Edwin VanCleef, un hombre que había reconstruido {link:stormwind-city}Ventormenta{/link} y no había recibido gratitud por ello.]=],
		},
		{
			title = "La carta del mensajero",
			hint = [=[Intercepte al mensajero de la Hermandad en los caminos de Páramos de Poniente.]=],
			text = [=[Un mensajero {link:defias-brotherhood}Defias{/link} recorría los caminos entre {link:moonbrook}Arroyo de la Luna{/link}, la cantera y la {link:jangolode-mine}Mina de Jango{/link}. El mensaje que llevaba era una prueba firme de que la {link:syndicate}Hermandad{/link} obedecía a VanCleef. No decía dónde se escondía.]=],
		},
		{
			title = "La guarida",
			hint = "Siga al traidor Defias hasta la guarida de la Hermandad.",
			text = [=[Un ladrón capturado compró su vida guiando a la milicia hasta {link:moonbrook}Arroyo de la Luna{/link}. Bajo la aldea, en la vieja mina de oro, VanCleef y sus canteros esperaban.]=],
		},
		{
			title = "La caída del cabecilla",
			hint = "Descienda al fondo de las Minas de la Muerte.",
			text = [=[En el fondo de las minas, sobre la cubierta de su barco, VanCleef se enfrentó a quienes habían venido a por él. No se rindió. Llamó a sus guardias a su lado y luchó, como {link:baros-alexston}Baros Alexston{/link} recordaba que luchaba en su juventud, sin igual. Cuando cayó, su cabeza fue llevada a la {link:sentinel-hill}Colina del Centinela{/link}.]=],
		},
		{
			title = "La carta sin enviar",
			hint = [=[Registre las pertenencias de VanCleef y entregue lo que encuentre.]=],
			text = [=[Entre las pertenencias de VanCleef había una carta sellada, nunca enviada, dirigida a {link:baros-alexston}Baros Alexston{/link}, el arquitecto de la ciudad de {link:stormwind-city}Ventormenta{/link}. Baros lo había conocido en el gremio. Al leerla, dijo que VanCleef seguía siendo un idealista y un romántico, un hombre consumido por la venganza. También confesó que no podía culparlo del todo.]=],
		},
	},
	mentions = {
		{
			text = [=[La {link:defias-brotherhood}Hermandad Defias{/link}, la nota del pícaro]=],
		},
		{
			text = [=[La {link:defias-brotherhood}Hermandad Defias{/link}, llevada a {link:master-mathias-shaw}Mathias Shaw{/link}]=],
		},
		{
			text = [=[{link:bazil-thredd}Bazil Thredd{/link}, de parte de {link:baros-alexston}Baros Alexston{/link}]=],
		},
		{ text = "Red Silk Bandanas" },
	},
	bonds = {
		{ id = "gryan-stoutmantle", name = "Gryan Stoutmantle", note = "le da caza" },
		{ id = "baros-alexston", name = "Baros Alexston", note = "antiguo cantero de su gremio" },
		{ id = "bazil-thredd", name = "Bazil Thredd", note = "su lugarteniente" },
		{ id = "master-mathias-shaw", name = "Maestro Mathias Shaw", note = "le puso nombre" },
		{ id = "tiffin-wrynn", name = "Tiffin Wrynn", note = "murió en el motín que él encabezó" },
		{ id = "captain-greenskin", name = "Capitán Greenskin", note = "capitán de su barco" },
		{ id = "the-defias-traitor", name = "El traidor Defias", note = "lo traicionó" },
	},
})

